solution.code:
function toggleDibeli(daftar, id) {
  const baru = daftar.map((b) => (b.id === id ? { ...b, dibeli: !b.dibeli } : b));
  return [...baru.filter((b) => !b.dibeli), ...baru.filter((b) => b.dibeli)];
}

