solution.code:
function validasiAkun(data) {
  const galat = [];
  const u = typeof data.username === "string" ? data.username.trim() : "";
  if (!/^[a-z0-9_]{3,20}$/.test(u)) galat.push("username");
  if (!Number.isInteger(data.umur) || data.umur < 13 || data.umur > 120) galat.push("umur");
  return galat;
}

