exercises.prompt:
Fungsi `rataRata` buatan AI hanya benar untuk input normal. Perbaiki sesuai spesifikasi:

- daftar kosong mengembalikan `null`;
- bila ada nilai yang bukan angka (termasuk teks seperti `"90"`) atau di luar 0 sampai 100, lempar `RangeError`;
- hasil dibulatkan ke 1 angka di belakang koma (pakai `Math.round(x * 10) / 10`).

starter.code:
function rataRata(nilai) {
  let total = 0;
  for (const n of nilai) total += n;
  return total / nilai.length;
}

solution.code:
function rataRata(nilai) {
  if (nilai.length === 0) return null;
  for (const n of nilai) {
    if (typeof n !== "number" || !Number.isFinite(n) || n < 0 || n > 100) {
      throw new RangeError("Nilai tidak valid: " + n);
    }
  }
  const total = nilai.reduce((a, b) => a + b, 0);
  return Math.round((total / nilai.length) * 10) / 10;
}

