solution.code:
function validasiPesanan(p) {
  const galat = [];
  const nama = typeof p.nama === "string" ? p.nama.trim() : "";
  if (nama.length < 1 || nama.length > 40) galat.push("nama");
  if (!MENU.some((m) => m.id === p.menu)) galat.push("menu");
  if (!Number.isInteger(p.jumlah) || p.jumlah < 1 || p.jumlah > 20) galat.push("jumlah");
  return galat;
}

function tambahPesanan(daftar, p) {
  const galat = validasiPesanan(p);
  if (galat.length) throw new Error("Pesanan tidak valid: " + galat.join(", "));
  const id = daftar.reduce((max, x) => Math.max(max, x.id), 0) + 1;
  return [...daftar, { id, nama: p.nama.trim(), menu: p.menu, jumlah: p.jumlah }];
}

function hitungTotal(daftar) {
  return daftar.reduce((total, p) => total + MENU.find((m) => m.id === p.menu).harga * p.jumlah, 0);
}

function escapeHtml(teks) {
  return String(teks)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function barisPesanan(p) {
  const menu = MENU.find((m) => m.id === p.menu);
  return "<li>" + escapeHtml(p.nama) + ": " + p.jumlah + "x " + menu.nama + "</li>";
}
